/* ===== Logo C.F.O embutida no código (não depende da pasta img nem de a Vercel entregar arquivos de imagem) =====
   CFO.LOGOS[tipo] = imagem em base64. tipo: completo | completo-escuro | icone | icone-escuro. Gerado a partir da logo do C.F.O. */
CFO.LOGOS = {
 "completo": "data:image/png;base64,",
 "completo-escuro": "data:image/png;base64,",
 "icone": "data:image/png;base64,",
 "icone-escuro": "data:image/png;base64,"
};
(() => {
  const liga = (rel, href) => { let l = document.querySelector('link[rel="' + rel + '"]'); if (!l) { l = document.createElement('link'); l.rel = rel; document.head.append(l); } l.href = href; };
  liga('icon', "data:image/png;base64,"); liga('apple-touch-icon', "data:image/png;base64,");
})();
